    Bug 460737 - Adjust Quick Filter for address book display name matching. r=aleca

    This patch adds Quick Filter matching for address book display names from contacts exposed through childCards, which includes local address books and synchronized CardDAV address books.

    I manually verified the behaviour with both a local address book and a Google CardDAV address book.

    I haven't attempted to extend the implementation to support online LDAP address books, as that appears to require a different approach using asynchronous directory searches.

    Differential Revision: https://phabricator.services.mozilla.com/D313242

diff --git a/mail/modules/QuickFilterManager.sys.mjs b/mail/modules/QuickFilterManager.sys.mjs
index f44236ae78f..2a0b9536a24 100644
--- a/mail/modules/QuickFilterManager.sys.mjs
+++ b/mail/modules/QuickFilterManager.sys.mjs
@@ -1101,6 +1101,51 @@ export var MessageTextFilter = {
     return terms;
   },

+  /**
+   * Finds email addresses for locally available contacts whose display name
+   * matches the given search phrase.
+   *
+   * @param {string} phrase - The search phrase entered by the user.
+   * @returns {Set<string>} Matching email addresses.
+   */
+  _getMatchingContactEmails(phrase) {
+    const emails = new Set();
+    const searchPhrase = phrase.trim().toLocaleLowerCase();
+
+    if (!searchPhrase) {
+      return emails;
+    }
+
+    for (const directory of MailServices.ab.directories) {
+      try {
+        for (const card of directory.childCards) {
+          const displayName = card.displayName?.toLocaleLowerCase();
+
+          if (
+            card.isMailList ||
+            !displayName ||
+            !displayName.includes(searchPhrase)
+          ) {
+            continue;
+          }
+
+          for (const emailAddress of card.emailAddresses) {
+            emails.add(emailAddress);
+          }
+        }
+      } catch (ex) {
+        console.error(
+          new Components.Exception(
+            `Exception thrown by ${directory.URI}: ${ex.message}`,
+            ex
+          )
+        );
+      }
+    }
+
+    return emails;
+  },
+
